#Requires -Version 5.1
# fix-planificador-movil-dashboard.ps1
# BUG 1 - Crash planificador movil:
#   unassignedVehicles usaba "vehiculos" pero el estado se llama "vehList"
#   -> ReferenceError en runtime -> crash en movil
#   FIX: vehiculos -> vehList
#
# BUG 2 - Dashboard muestra no asignables:
#   La query de RRHH no cargaba el campo "asignable", por lo que
#   aparecian todos los empleados activos aunque estuvieran marcados
#   como no asignables (ej: personal de oficina, bajas, etc.)
#   FIX: cargar campo asignable en la query + filtrar igual que el planificador
#   (activo=true Y asignable !== false)

$ErrorActionPreference = "Stop"
$RepoPath = "C:\Users\lauro\Desktop\LOYNEK\ObrasPlan\obrasplan-mvp\obrasplan"
if (-not (Test-Path $RepoPath)) { Write-Host "ERROR" -ForegroundColor Red; exit 1 }
Set-Location $RepoPath
git pull --quiet 2>$null
Write-Host "" ; Write-Host "==> Fix planificador movil + dashboard filtro" -ForegroundColor Cyan

Write-Host "  -> src\app\planificacion\page.tsx" -ForegroundColor Gray
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\planificacion\page.tsx"), $bytes)
Write-Host "  OK: 70 KB" -ForegroundColor Green

Write-Host "  -> src\app\dashboard\page.tsx" -ForegroundColor Gray
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\dashboard\page.tsx"), $bytes)
Write-Host "  OK: 33 KB" -ForegroundColor Green

$plan = [System.IO.File]::ReadAllText((Join-Path $RepoPath "src\app\planificacion\page.tsx"), [System.Text.Encoding]::UTF8)
$dash = [System.IO.File]::ReadAllText((Join-Path $RepoPath "src\app\dashboard\page.tsx"), [System.Text.Encoding]::UTF8)
if ($plan.Contains("vehList.filter") -and -not $plan.Contains("vehiculos.filter((v)")) { Write-Host "  OK: vehList fix (crash movil resuelto)" -ForegroundColor Green } else { Write-Host "  ERROR plan" -ForegroundColor Red }
if ($dash.Contains("rrhhAsignableIds")) { Write-Host "  OK: filtro asignable en dashboard" -ForegroundColor Green } else { Write-Host "  ERROR dash" -ForegroundColor Red }
Write-Host ""
Write-Host "  git add src\app\planificacion\page.tsx src\app\dashboard\page.tsx"
Write-Host '  git commit -m "fix: crash movil vehList + dashboard filtro asignable"'
Write-Host "  git push"
